"""Synthetic HAR-like dataset: per-subject continuous 3-channel signals cut into 8-sample windows with 50% overlap
(so a random-row split leaks half-windows, as in UCI HAR). 12 subjects, 3 activity classes."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

import numpy as np


def make(out: Path, subjects: int = 12, seed: int = 0) -> Path:
    rng = np.random.default_rng(seed)
    X, y, g, ids = [], [], [], []
    for s in range(subjects):
        for c in range(3):
            sig = rng.normal(c * 1.5, 0.6, size=(40, 3)).astype("float32")
            for start in range(0, 40 - 8 + 1, 4):
                X.append(sig[start : start + 8])
                y.append(c)
                g.append(f"s{s:02d}")
                ids.append(f"s{s:02d}-c{c}-w{start}")
    out.mkdir(parents=True, exist_ok=True)
    np.savez(out / "data.npz", X=np.stack(X), y=np.array(y), group=np.array(g), sample_id=np.array(ids))
    sha = hashlib.sha256((out / "data.npz").read_bytes()).hexdigest()
    (out / "manifest.json").write_text(
        json.dumps(
            {
                "name": "synthetic_har",
                "version": "1",
                "source": "generated by tests/fixtures/make_dataset.py",
                "license": "CC0 (synthetic)",
                "group_key": "subject",
                "overlapping_windows": True,
                "table": "data.npz",
                "files": [{"path": "data.npz", "sha256": sha}],
            }
        )
    )
    return out
